import itertools
import random
import collections

def is_3_colorable(edges):
    adj = [[] for _ in range(16)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    colors = [-1] * 16
    def bt(i):
        if i == 16:
            return True
        used = set()
        for nei in adj[i]:
            if colors[nei] != -1:
                used.add(colors[nei])
        for c in range(3):
            if c not in used:
                colors[i] = c
                if bt(i + 1):
                    return True
        colors[i] = -1
        return False
    return bt(0)

def find_girth(edges):
    adj = [[] for _ in range(16)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    girth = 17
    for start in range(16):
        dist = [-1] * 16
        dist[start] = 0
        parent = [-1] * 16
        q = collections.deque([start])
        while q:
            u = q.popleft()
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    q.append(v)
                elif v != parent[u]:
                    cycle = dist[u] + dist[v] + 1
                    if cycle < girth:
                        girth = cycle
    return girth

possible_edges = [(i, j) for i in range(16) for j in range(i + 1, 16)]
random.seed(42)  # for reproducibility
found = False
selected_edges = None
for trial in range(1000):
    selected = random.sample(possible_edges, 21)
    g = find_girth(selected)
    if g >= 8:
        if is_3_colorable(selected):
            found = True
            selected_edges = sorted(selected)
            break
print(found)
if found:
    print(selected_edges)

